import type { Hono } from "hono";
import { find } from "../runtime/store.js";
import { StepError } from "../runtime/step.js";
import { validate } from "../runtime/validate.js";
import type { Service, Slot, Client, Booking } from "../types.js";
import { bookSlot } from "../steps/book_slot.js";

export function routeBook(app: Hono): void {
  app.post("/book", async (ctx) => {
    const checked = validate(
      {
        client: { kind: "ref", table: "Client" },
        slot: { kind: "ref", table: "Slot" },
      },
      await ctx.req.json().catch(() => undefined),
      false,
    );
    if (checked.issues.length) {
      return ctx.json({ error: "invalid_input", issues: checked.issues }, 400);
    }
    try {
      const client = find("Client", checked.values.client as string) as Client;
      const slot = find("Slot", checked.values.slot as string) as Slot;
      const booking = await bookSlot(client, slot);
      return ctx.json(booking);
    } catch (error) {
      if (error instanceof StepError) {
        return ctx.json({ error: error.code }, error.code === "not_found" ? 404 : 422);
      }
      throw error;
    }
  });
}
